// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz parameters: from (caller), v (value), single recipient to keep external calls count small but variable
    function testFuzz_property(address from, uint256 v, address dummy) public {
        // keep recipient list length exactly 1 so helper records one call
        vm.assume(dummy != address(0));
        address[] memory tos = new address[](1);
        tos[0] = dummy;

        // Deploy a recorder that implements the correct selector signature:
        // function transferFrom(address from, address to, uint256 v) external returns (bool);
        Recorder rec = new Recorder();

        // The general rule: reference C will call callee.transferFrom(from, to, v) which exists on Recorder
        // For the mutant, the selector is wrong and Recorder's function will NOT be invoked; the low-level call will fail

        // Call transfer through c. We wrap in try/catch to observe whether it reverts (ok=false) or returns (ok=true)
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference ALWAYS succeeds (returns true) because Recorder exposes the exact expected function and it returns true.
        // The mutant can fail for some inputs (it will attempt to call a non-existent selector on Recorder), so the property
        // we assert is that the call succeeded. This holds for the reference for all inputs; the mutant will violate it
        // for some fuzzed inputs (the fuzzer will find such a case).
        assertTrue(ok);
    }
}

// Recorder exposes the exact ABI the reference expects and records that it was called.
contract Recorder {
    // storage to observe calls
    event Called(address indexed from, address indexed to, uint256 v);

    // matches selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address _from, address _to, uint256 _v) external returns (bool) {
        emit Called(_from, _to, _v);
        return true;
    }
}
